import { PlaceHolderImages } from '@/lib/placeholder-images';
import type { Panel, Tool } from '@/lib/tools-data';
import Image from 'next/image';
import { AISuggestions } from './ai-suggestions';
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from '../ui/card';
import { ScrollArea } from '../ui/scroll-area';
import { Textarea } from '../ui/textarea';
import { Box, Music } from 'lucide-react';

type PanelProps = {
  panel: Panel;
  toolType: Tool['name'];
};

export function ForgePanel({ panel, toolType }: PanelProps) {
  const renderContent = () => {
    switch (panel.type) {
      case 'editor':
        return (
          <ScrollArea className="h-64">
            <Textarea
              defaultValue={panel.content}
              className="h-full min-h-64 w-full resize-none border-0 p-1 focus-visible:ring-0"
              aria-label={panel.title}
            />
          </ScrollArea>
        );
      case 'media':
        const image = PlaceHolderImages.find((img) => img.id === panel.imageId);
        if (!image) {
          return (
            <div className="flex h-64 items-center justify-center rounded-md bg-muted text-muted-foreground">
              Image not found
            </div>
          );
        }
        return (
          <div className="relative h-64 w-full overflow-hidden rounded-md">
            <Image
              src={image.imageUrl}
              alt={image.description}
              fill
              className="object-cover"
              data-ai-hint={image.imageHint}
            />
          </div>
        );
      case 'sound':
        return (
          <div className="flex h-64 flex-col items-center justify-center gap-4 rounded-md bg-muted text-muted-foreground">
            <Music className="size-16" />
            <span className="font-mono text-sm">{panel.content}</span>
          </div>
        );
      case '3d':
        return (
          <div className="flex h-64 flex-col items-center justify-center gap-4 rounded-md bg-muted text-muted-foreground">
            <Box className="size-16" />
            <span className="font-mono text-sm">{panel.content}</span>
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <Card className="flex h-full flex-col">
      <CardHeader>
        <CardTitle>{panel.title}</CardTitle>
        <CardDescription>{panel.purpose}</CardDescription>
      </CardHeader>
      <CardContent className="flex-grow">{renderContent()}</CardContent>
      <CardFooter>
        <AISuggestions
          panelContent={panel.content}
          panelPurpose={panel.purpose}
          toolType={toolType}
        />
      </CardFooter>
    </Card>
  );
}
